package android.app;
public class TaskStackBuilder { private final android.content.Context context; private final java.util.ArrayList<android.content.Intent> intents=new java.util.ArrayList<android.content.Intent>(); private TaskStackBuilder(android.content.Context c) { context=c; } public static TaskStackBuilder create(android.content.Context c) { return new TaskStackBuilder(c); } public TaskStackBuilder addNextIntent(android.content.Intent i) { intents.add(i); return this; } public TaskStackBuilder addNextIntentWithParentStack(android.content.Intent i) { return addNextIntent(i); } public TaskStackBuilder addParentStack(Activity activity) { return this; } public int getIntentCount() { return intents.size(); } public void startActivities() { for(android.content.Intent i:intents) context.startActivity(i); } }
